// Revealer — Gtk.Revealer
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles revealer with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { RevealerTransitionType } from "@/lib/enums"

export interface RevealerProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.Revealer */
  child?: ReactNode

  /** gboolean, from Gtk.Revealer */
  revealChild?: boolean

  /** guint, from Gtk.Revealer */
  transitionDuration?: number

  /** RevealerTransitionType, from Gtk.Revealer */
  transitionType?: RevealerTransitionType
}

export function Revealer({ className, children }: RevealerProps) {
  return (
    <div className={cn("py-0", "px-3.5", className)}>
      {children}
    </div>
  )
}
